const key = (env.get("OPENWEATHER_API_KEY") || "").trim();
if (!key) {
    return [null, { payload: "Meteorología: falta OPENWEATHER_API_KEY" }];
}
const city = (env.get("OPENWEATHER_CITY") || "Vigo,ES").trim() || "Vigo,ES";
const url = "https://api.openweathermap.org/data/2.5/weather"
    + "?q=" + encodeURIComponent(city)
    + "&units=metric&lang=es&appid=" + encodeURIComponent(key);
return [{ url, requestTimeout: 10000 }, null];

const data = msg.payload;
if (msg.statusCode !== 200) {
    const hint = {
        401: "verifica la activación de la clave",
        404: "revisa OPENWEATHER_CITY",
        429: "límite de consultas alcanzado"
    }[msg.statusCode];
    return { payload: "Meteorología no disponible (HTTP " + msg.statusCode
        + (hint ? ": " + hint : "") + ")" };
}
if (!data || !Number.isFinite(data.main?.temp)
    || !Number.isFinite(data.main?.humidity) || !Number.isFinite(data.dt)
    || !data.name || !data.weather?.[0]?.description) {
    return { payload: "Meteorología: respuesta incompleta" };
}
const weather = {
    city: data.name,
    country: data.sys?.country,
    temperatureC: data.main.temp,
    feelsLikeC: data.main.feels_like,
    humidityPct: data.main.humidity,
    pressureHpa: data.main.pressure,
    windSpeedMs: data.wind?.speed,
    description: data.weather[0].description,
    observedAt: new Date(data.dt * 1000).toISOString(),
    conditionId: data.weather[0].id,
    rain: (data.weather[0].id >= 200 && data.weather[0].id < 700) ||
        !!(data.rain && Object.values(data.rain).some(x => typeof x === 'number' && x > 0)) ||
        !!(data.snow && Object.values(data.snow).some(x => typeof x === 'number' && x > 0)),
    storm: data.weather[0].id >= 200 && data.weather[0].id < 300
};
const time = new Intl.DateTimeFormat("es-ES", {
    timeZone: "Europe/Madrid", hour: "2-digit", minute: "2-digit",
    day: "2-digit", month: "2-digit"
}).format(new Date(weather.observedAt));
return {
    weather,
    payload: weather.city + " · " + weather.temperatureC.toFixed(1) + " °C · "
        + weather.humidityPct + " % HR · " + weather.description + " · " + time
};

if (!msg.weather) return null;
const id = msg.weather.conditionId || 800;
let icon = '🌤️';
if (id >= 200 && id < 300) icon = '⛈️';
else if (id >= 300 && id < 600) icon = '🌧️';
else if (id >= 600 && id < 700) icon = '❄️';
else if (id >= 700 && id < 800) icon = '🌫️';
else if (id === 800) icon = '☀️';
else if (id === 801 || id === 802) icon = '⛅';
else if (id >= 803) icon = '☁️';

return {
    topic: 'bunkeros/weather',
    payload: {
        ciudad: msg.weather.city,
        temperatura: msg.weather.temperatureC,
        sensacion: msg.weather.feelsLikeC,
        humedad: msg.weather.humidityPct,
        presion: msg.weather.pressureHpa,
        viento: msg.weather.windSpeedMs,
        descripcion: msg.weather.description,
        icon: icon,
        lluvia: typeof msg.weather.rain === 'boolean' ? msg.weather.rain : false,
        tormenta: typeof msg.weather.storm === 'boolean' ? msg.weather.storm : false,
        observedAt: msg.weather.observedAt
    }
};

const defaults = {
    calor: false,
    humedad: false,
    reservaBaja: false,
    fuga: false,
    escotillaAbierta: false,
    gas: false
};
let estados = Object.assign({}, defaults, flow.get('escenarios') || {});
const comando = msg.payload;
if (comando === 'reset') {
    estados = { ...defaults };
} else if (Object.prototype.hasOwnProperty.call(defaults, comando)) {
    estados[comando] = !estados[comando];
} else {
    return null;
}
flow.set('escenarios', estados);
msg.payload = estados;
return msg;

// DHT22 + MQ-2 virtuales: gas_ppm es una SIMULACION, no una medida calibrada.
const s = flow.get('escenarios') || {};
msg.topic = 'sensor/dht11';
msg.payload = {
    temperature_c: Number((s.calor ? 34 + Math.random() : 23 + Math.random() * 3).toFixed(1)),
    humidity_pct: Number((s.humedad ? 78 + Math.random() : 50 + Math.random() * 10).toFixed(1)),
    gas_ppm: Number((s.gas ? 420 + Math.random() * 60 : 95 + Math.random() * 55).toFixed(0))
};
return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/reed";
msg.payload = {
    hatch_state: s.escotillaAbierta ? "open" : "closed"
};

return msg;

const s = flow.get('escenarios') || {};
msg.topic = 'sensor/ultrasonico';
msg.payload = {
    // Rango normal por debajo de 80%, para ensayar reapertura automática.
    tank_level_pct: Number((s.reservaBaja ? 12 + Math.random() * 3 : 74 + Math.random() * 5).toFixed(1))
};
return msg;

const s = flow.get("escenarios") || {};

msg.topic = "sensor/fuga";
msg.payload = {
    leak_detected: !!s.fuga
};

return msg;

const BASE = env.get("MQTT_BASE_TOPIC");
let datos = flow.get('sensores') || {};
const estado = flow.get('actuadores_simulados') || {};

switch (msg.topic) {
    case 'sensor/dht11': datos.ambiente = msg.payload; break;
    case 'sensor/reed': datos.acceso = msg.payload.hatch_state; break;
    default: return null;
}
flow.set('sensores', datos);
const timestamp = new Date().toISOString();
const salida = [null, null];

if (msg.topic === 'sensor/dht11' && datos.ambiente) {
    salida[0] = {
        topic: BASE + '/telemetria/ambiente', qos: 0, retain: false,
        payload: {
            device_id: 'esp32-env-01',
            temperature_c: datos.ambiente.temperature_c,
            humidity_pct: datos.ambiente.humidity_pct,
            gas_ppm: datos.ambiente.gas_ppm,
            fan_state: estado.fan_state || null,
            timestamp,
            simulated: true
        }
    };
}
if (msg.topic === 'sensor/reed') {
    salida[1] = {
        topic: BASE + '/telemetria/acceso', qos: 1, retain: true,
        payload: {device_id: 'esp32-env-01', hatch_state: datos.acceso, timestamp, simulated: true}
    };
}
return salida;

const BASE = env.get("MQTT_BASE_TOPIC");
if (msg.topic !== BASE + '/telemetria/hidrico') return null;
const p = msg.payload;
if (!p || typeof p.leak_detected !== 'boolean') return null;
const fuga = p.leak_detected;
const anterior = context.get('fugaAnterior');
if (anterior === fuga) return null;
if (fuga && p.valve_state !== 'CLOSED') {
    node.warn('Fuga detectada sin confirmación de cierre: no se declara cierre ejecutado');
    return null;
}
context.set('fugaAnterior', fuga);
return {
    topic: BASE + '/alerta/fuga', qos: 1, retain: true,
    payload: {
        device_id: p.device_id || 'esp32-water-01',
        severity: fuga ? 'CRITICAL' : 'INFO',
        event: fuga ? 'WATER_LEAK_TRIGGERED' : 'WATER_LEAK_CLEARED',
        active: fuga,
        ...(fuga ? {action_taken: 'VALVE_CLOSED_IMMEDIATELY'} : {}),
        simulated: true,
        timestamp: new Date().toISOString()
    }
};

const BASE = env.get("MQTT_BASE_TOPIC");
if (msg.topic !== BASE + '/telemetria/acceso') return null;
const p = msg.payload;
if (!p || !['open', 'closed'].includes(p.hatch_state)) return null;

// Por defecto arranca ARMADO (true) a menos que se haya puesto en DISARM explícitamente
const modo = flow.get('modoProteccion');
const armado = modo !== false; 
const anterior = context.get('estadoAnterior');
let alarmaActiva = context.get('alarmaActiva') === true;
context.set('estadoAnterior', p.hatch_state);

if (armado && p.hatch_state === 'open' && !alarmaActiva) {
    context.set('alarmaActiva', true);
    return {
        topic: BASE + '/alerta/escotilla', qos: 1, retain: true,
        payload: {
            device_id: p.device_id || 'esp32-water-01',
            severity: 'CRITICAL',
            event: 'UNAUTHORIZED_HATCH_OPEN',
            active: true,
            simulated: true,
            timestamp: new Date().toISOString()
        }
    };
}
if ((p.hatch_state === 'closed' || !armado) && alarmaActiva) {
    context.set('alarmaActiva', false);
    return {
        topic: BASE + '/alerta/escotilla', qos: 1, retain: true,
        payload: {
            device_id: p.device_id || 'esp32-water-01',
            severity: 'INFO',
            event: 'HATCH_ALERT_CLEARED',
            active: false,
            simulated: true,
            timestamp: new Date().toISOString()
        }
    };
}
return null;

const BASE = env.get("MQTT_BASE_TOPIC");
if (msg.topic !== BASE + '/telemetria/hidrico') return null;
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {try {p = JSON.parse(p);} catch (e) {return null;}}
if (!p || typeof p !== 'object') return null;
const nivel = p.tank_level_pct;
if (typeof nivel !== 'number' || !Number.isFinite(nivel) || nivel < 0 || nivel > 100) return null;
const alerta = nivel < 60;
const anterior = context.get('reservaBajaAnterior');
if (anterior === alerta) return null;
context.set('reservaBajaAnterior', alerta);
return {
    topic: BASE + '/alerta/hidrico', qos: 1, retain: true,
    payload: {device_id: p.device_id || 'esp32-water-01',
        severity: alerta ? 'WARNING' : 'INFO',
        event: alerta ? 'LOW_WATER_LEVEL' : 'WATER_LEVEL_RECOVERED',
        tank_level_pct: nivel, threshold_pct: 60, active: alerta,
        simulated: true, timestamp: new Date().toISOString()}
};

const BASE = env.get("MQTT_BASE_TOPIC");
let estado = flow.get("actuadores_simulados") || {
    fan_state: "OFF",
    valve_state: "OPEN",
    fan_mode: "AUTO",
    valve_mode: "AUTO",
    fan_error: null,
    valve_error: null
};

let sensores = flow.get("sensores") || {};
let modoProteccion = flow.get("modoProteccion");
if (modoProteccion === undefined) modoProteccion = true;

const t = msg.topic;
let p = msg.payload;

if (typeof p === "string") {
    try { 
        p = JSON.parse(p); 
    } catch (e) {
        if (!["ARM", "DISARM", "ON", "OFF", "AUTO"].includes(p)) {
            node.warn("Payload no reconocido o JSON no valido en " + t + ": " + p);
            return null;
        }
    }
}

let eventMsg = null;
let stateChanged = false;
let commandResult = null;

if (t === BASE + "/control/seguridad") {
    const accion = typeof p === "object" ? p.action : p;
    if (accion === "ARM") {
        modoProteccion = true;
        flow.set("modoProteccion", true);
        eventMsg = {
            topic: BASE + "/evento/seguridad", qos: 1, retain: true,
            payload: { device_id: "esp32-water-01", event: "ACCEPTED_ARM", severity: "INFO", timestamp: new Date().toISOString() }
        };
        stateChanged = true;
    } else if (accion === "DISARM") {
        modoProteccion = false;
        flow.set("modoProteccion", false);
        eventMsg = {
            topic: BASE + "/evento/seguridad", qos: 1, retain: true,
            payload: { device_id: "esp32-water-01", event: "ACCEPTED_DISARM", severity: "INFO", timestamp: new Date().toISOString() }
        };
        stateChanged = true;
    }
}

if (t === BASE + "/control/ventilacion") {
    const accion = typeof p === "object" ? p.action : p;
    const tempActual = (sensores.ambiente && typeof sensores.ambiente.temperature_c === "number") ? sensores.ambiente.temperature_c : 24;

    if (accion === "AUTO") {
        estado.fan_mode = "AUTO";
        estado.fan_error = null;
        commandResult = "ACCEPTED_AUTO";
        stateChanged = true;
    } else if (accion === "ON") {
        estado.fan_mode = "MANUAL";
        estado.fan_state = "ON";
        estado.fan_error = null;
        commandResult = "ACCEPTED_MANUAL_ON";
        stateChanged = true;
        eventMsg = {
            topic: BASE + "/evento/ventilacion", qos: 1, retain: true,
            payload: { device_id: "esp32-env-01", event: "FAN_ON", state: "ON", mode: "MANUAL", timestamp: new Date().toISOString() }
        };
    } else if (accion === "OFF") {
        if (tempActual >= 30) {
            estado.fan_error = "safety_override_active";
            commandResult = "REJECTED_SAFETY_OVERRIDE";
            stateChanged = true;
        } else {
            estado.fan_mode = "MANUAL";
            estado.fan_state = "OFF";
            estado.fan_error = null;
            commandResult = "ACCEPTED_MANUAL_OFF";
            stateChanged = true;
            eventMsg = {
                topic: BASE + "/evento/ventilacion", qos: 0, retain: false,
                payload: { device_id: "esp32-env-01", event: "FAN_OFF", state: "OFF", mode: "MANUAL", timestamp: new Date().toISOString() }
            };
        }
    }
}

if (t === BASE + "/control/valvula") {
    const accion = typeof p === "object" ? p.action : p;
    const hayFuga = sensores.fuga && sensores.fuga.leak_detected === true;

    if (accion === "AUTO") {
        estado.valve_mode = "AUTO";
        estado.valve_error = null;
        commandResult = "ACCEPTED_AUTO";
        stateChanged = true;
    } else if (accion === "OPEN") {
        if (hayFuga) {
            estado.valve_error = "interlock_active";
            commandResult = "REJECTED_INTERLOCK";
            stateChanged = true;
        } else {
            estado.valve_mode = "MANUAL";
            estado.valve_state = "OPEN";
            estado.valve_error = null;
            commandResult = "ACCEPTED_MANUAL_OPEN";
            stateChanged = true;
            eventMsg = {
                topic: BASE + "/evento/hidrico", qos: 1, retain: true,
                payload: { device_id: "esp32-water-01", event: "VALVE_OPENED", state: "OPEN", mode: "MANUAL", timestamp: new Date().toISOString() }
            };
        }
    } else if (accion === "CLOSE") {
        estado.valve_mode = "MANUAL";
        estado.valve_state = "CLOSED";
        estado.valve_error = null;
        commandResult = "ACCEPTED_MANUAL_CLOSE";
        stateChanged = true;
        eventMsg = {
            topic: BASE + "/evento/hidrico", qos: 0, retain: false,
            payload: { device_id: "esp32-water-01", event: "VALVE_CLOSED", state: "CLOSED", mode: "MANUAL", timestamp: new Date().toISOString() }
        };
    }
}

if (t === BASE + "/telemetria/hidrico") {
    sensores.fuga = { leak_detected: p.leak_detected };
    flow.set("sensores", sensores);

    if (p.leak_detected === true) {
        if (estado.valve_state !== "CLOSED") {
            estado.valve_state = "CLOSED";
            estado.valve_error = "interlock_active";
            stateChanged = true;
            eventMsg = {
                topic: BASE + "/evento/hidrico", qos: 1, retain: true,
                payload: { device_id: "esp32-water-01", event: "VALVE_CLOSED", reason: "INTERLOCK_LEAK", timestamp: new Date().toISOString() }
            };
        }
    } else if (estado.valve_mode === "AUTO") {
        if (typeof p.tank_level_pct === "number") {
            if (p.tank_level_pct <= 80 && estado.valve_state !== "OPEN") {
                estado.valve_state = "OPEN";
                stateChanged = true;
                eventMsg = {
                    topic: BASE + "/evento/hidrico", qos: 1, retain: true,
                    payload: { device_id: "esp32-water-01", event: "VALVE_OPENED", reason: "AUTO_REFILL", timestamp: new Date().toISOString() }
                };
            } else if (p.tank_level_pct >= 100 && estado.valve_state !== "CLOSED") {
                estado.valve_state = "CLOSED";
                stateChanged = true;
                eventMsg = {
                    topic: BASE + "/evento/hidrico", qos: 0, retain: false,
                    payload: { device_id: "esp32-water-01", event: "VALVE_CLOSED", reason: "AUTO_FULL", timestamp: new Date().toISOString() }
                };
            }
        }
    }
}

if (t === BASE + "/telemetria/ambiente") {
    sensores.ambiente = p;
    flow.set("sensores", sensores);

    if (typeof p.temperature_c === "number") {
        if (p.temperature_c >= 30) {
            if (estado.fan_state !== "ON") {
                estado.fan_state = "ON";
                stateChanged = true;
                eventMsg = {
                    topic: BASE + "/evento/ventilacion", qos: 1, retain: true,
                    payload: { device_id: "esp32-env-01", event: "FAN_ON", reason: "SAFETY_OVERTEMP", timestamp: new Date().toISOString() }
                };
            }
        } else if (estado.fan_mode === "AUTO" && p.temperature_c < 28) {
            if (estado.fan_state !== "OFF") {
                estado.fan_state = "OFF";
                stateChanged = true;
                eventMsg = {
                    topic: BASE + "/evento/ventilacion", qos: 0, retain: false,
                    payload: { device_id: "esp32-env-01", event: "FAN_OFF", reason: "AUTO_NORMAL", timestamp: new Date().toISOString() }
                };
            }
        }
    }
}

flow.set("actuadores_simulados", estado);

let statusMsg = null;
if (stateChanged || commandResult) {
    statusMsg = {
        topic: BASE + "/estado/actuadores", qos: 1, retain: true,
        payload: {
            fan_state: estado.fan_state,
            valve_state: estado.valve_state,
            fan_mode: estado.fan_mode,
            valve_mode: estado.valve_mode,
            fan_error: estado.fan_error,
            valve_error: estado.valve_error,
            command_result: commandResult,
            modo_proteccion: modoProteccion ? "ARM" : "DISARM",
            timestamp: new Date().toISOString()
        }
    };
}

let telemetriaEnriquecida = null;
if (t === BASE + "/telemetria/hidrico") {
    telemetriaEnriquecida = Object.assign({}, msg, {
        payload: Object.assign({}, p, { valve_state: estado.valve_state })
    });
} else if (t === BASE + "/telemetria/ambiente") {
    telemetriaEnriquecida = Object.assign({}, msg, {
        payload: Object.assign({}, p, { fan_state: estado.fan_state })
    });
}

return [eventMsg, statusMsg, telemetriaEnriquecida];

