    fan_state: "OFF",
    valve_state: "OPEN",
    fan_mode: "AUTO",
    valve_mode: "AUTO",
    fan_error: null,
    valve_error: null,
    timestamp: new Date().toISOString()
};
flow.set("actuadores_simulados", estadoInicial);

