const BASE = env.get("MQTT_BASE_TOPIC");
let datos = flow.get('sensores') || {};
const estado = flow.get('actuadores_simulados') || {};

switch (msg.topic) {
    case 'sensor/ultrasonico': datos.hidrico = msg.payload; break;
    case 'sensor/fuga': datos.fuga = msg.payload.leak_detected; break;
    default: return null;
}
flow.set('sensores', datos);
const timestamp = new Date().toISOString();

if (datos.hidrico) {
    return {
        topic: BASE + '/telemetria/hidrico', qos: 0, retain: false,
        payload: {
            device_id: 'esp32-water-01',
            tank_level_pct: datos.hidrico.tank_level_pct,
            distance_cm: datos.hidrico.distance_cm,
            leak_detected: datos.fuga || false,
            valve_state: estado.valve_state || null,
            timestamp,
            simulated: true
        }
    };
}
return null;

const BASE = env.get("MQTT_BASE_TOPIC");
if (msg.topic !== BASE + '/telemetria/ambiente') return null;
const p = msg.payload;
if (!p || typeof p !== 'object') return null;

const temp = typeof p.temperature_c === 'number' ? p.temperature_c : null;
if (temp === null) return null;

const calor = temp >= 30;
const calorAnt = context.get('calorAnterior');
if (calorAnt === calor) return null;
context.set('calorAnterior', calor);

return {
    topic: BASE + '/alerta/temperatura',
    qos: 1,
    retain: true,
    payload: {
        device_id: p.device_id || 'esp32-env-01',
        severity: calor ? 'WARNING' : 'INFO',
        event: calor ? 'HIGH_TEMPERATURE' : 'TEMPERATURE_NORMAL',
        alert_id: 'calor',
        text: 'Temperatura elevada (>= 30 °C)',
        active: calor,
        value: temp,
        simulated: true,
        timestamp: new Date().toISOString()
    }
};

const BASE = env.get("MQTT_BASE_TOPIC");
if (msg.topic !== BASE + '/telemetria/ambiente') return null;
const p = msg.payload;
if (!p || typeof p !== 'object') return null;

const hum = typeof p.humidity_pct === 'number' ? p.humidity_pct : null;
if (hum === null) return null;

const humedad = hum >= 70;
const humedadAnt = context.get('humedadAnterior');
if (humedadAnt === humedad) return null;
context.set('humedadAnterior', humedad);

return {
    topic: BASE + '/alerta/humedad',
    qos: 1,
    retain: true,
    payload: {
        device_id: p.device_id || 'esp32-env-01',
        severity: humedad ? 'WARNING' : 'INFO',
        event: humedad ? 'HIGH_HUMIDITY' : 'HUMIDITY_NORMAL',
        alert_id: 'humedad',
        text: 'Humedad elevada (>= 70 %)',
        active: humedad,
        value: hum,
        simulated: true,
        timestamp: new Date().toISOString()
    }
};

const now = Date.now();
const state = global.get("bunkerCore") || {
  data: {
    temperatura: null,
    humedad: null,
    nivelAgua: null,
    puertaAbierta: null,
    fugaAgua: false,
    fanEstado: "OFF",
    valvulaEstado: "OPEN",
    fanMode: "AUTO",
    valvulaMode: "AUTO",
    modoSeguridad: "ARM"
  },
  meteo: null,
  history: [],
  events: [],
  activeAlerts: {},
  lastUpdate: null,
  lastCommand: null
};

if (!state.activeAlerts) state.activeAlerts = {};
if (!state.data.fanMode) state.data.fanMode = "AUTO";
if (!state.data.valvulaMode) state.data.valvulaMode = "AUTO";
if (!state.data.modoSeguridad) state.data.modoSeguridad = "ARM";

let p = msg.payload;
if (typeof p === "string") {
  try { p = JSON.parse(p); } catch (_) {}
}

const HUMAN_EVENTS = {
  "FAN_ON": "Extractor de aire encendido",
  "FAN_OFF": "Extractor de aire apagado",
  "VALVE_OPENED": "Valvula de agua abierta",
  "VALVE_CLOSED": "Valvula de agua cerrada",
  "WATER_LEAK_TRIGGERED": "Alerta critica: Fuga de agua detectada en suelo",
  "WATER_LEAK_CLEARED": "Fuga de agua resuelta",
  "UNAUTHORIZED_HATCH_OPEN": "Alerta de intrusion: Escotilla abierta sin autorizacion",
  "HATCH_ALERT_CLEARED": "Escotilla cerrada / Perimetro asegurado",
  "LOW_WATER_LEVEL": "Aviso: Reserva hidrica baja (< 60 %)",
  "WATER_LEVEL_RECOVERED": "Reserva hidrica recuperada",
  "HIGH_TEMPERATURE": "Alerta: Temperatura elevada en cabina (>= 30 C)",
  "TEMPERATURE_NORMAL": "Temperatura interior normalizada",
  "HIGH_HUMIDITY": "Alerta: Humedad relativa elevada (>= 70 %)",
  "HUMIDITY_NORMAL": "Humedad relativa normalizada",
  "REJECTED_INTERLOCK": "Comando rechazado: Interbloqueo de seguridad por fuga activo",
  "REJECTED_SAFETY_OVERRIDE": "Comando rechazado: Ventilacion forzada por alta temperatura",
  "ACCEPTED_ARM": "Perimetro armado (Modo Sellado activo)",
  "ACCEPTED_DISARM": "Perimetro desarmado (Acceso autorizado)"
};

if (msg.topic === "bunkeros/weather") {
  if (p && typeof p === "object") {
    state.meteo = {
      ciudad: String(p.ciudad || "Localidad"),
      temperatura: typeof p.temperatura === "number" ? p.temperatura : null,
      sensacion: typeof p.sensacion === "number" ? p.sensacion : null,
      humedad: typeof p.humedad === "number" ? p.humedad : null,
      presion: typeof p.presion === "number" ? p.presion : null,
      viento: typeof p.viento === "number" ? p.viento : null,
      descripcion: String(p.descripcion || ""),
      icon: p.icon || "🌤️",
      lluvia: Boolean(p.lluvia),
      tormenta: Boolean(p.tormenta),
      observedAt: p.observedAt || null,
      ts: now
    };
  }
} else if (msg.topic && typeof msg.topic === "string") {
  const t = msg.topic;

  // --- CANAL DE TELEMETRIA ---
  if (t.includes("/telemetria/")) {
    state.lastUpdate = now;
    if (t.endsWith("/ambiente")) {
      if (typeof p.temperature_c === "number") state.data.temperatura = p.temperature_c;
      if (typeof p.humidity_pct === "number") state.data.humedad = p.humidity_pct;
      if (p.fan_state) state.data.fanEstado = p.fan_state;
    } else if (t.endsWith("/hidrico")) {
      if (typeof p.tank_level_pct === "number") state.data.nivelAgua = p.tank_level_pct;
      if (typeof p.leak_detected === "boolean") state.data.fugaAgua = p.leak_detected;
      if (p.valve_state) state.data.valvulaEstado = p.valve_state;
    } else if (t.endsWith("/acceso")) {
      if (p.hatch_state) state.data.puertaAbierta = (p.hatch_state === "open");
      else if (typeof p.open === "boolean") state.data.puertaAbierta = p.open;
    }

    if (state.data.temperatura !== null && state.data.nivelAgua !== null) {
      state.history.push({ ts: now, temperatura: state.data.temperatura, humedad: state.data.humedad, nivelAgua: state.data.nivelAgua });
      state.history = state.history.slice(-50);
    }
  }

  // --- CANAL DE ESTADOS DE ACTUADORES ---
  else if (t.endsWith("/estado/actuadores")) {
    state.lastUpdate = now;
    if (p.fan_state) state.data.fanEstado = p.fan_state;
    if (p.valve_state) state.data.valvulaEstado = p.valve_state;
    if (p.fan_mode) state.data.fanMode = p.fan_mode;
    if (p.valve_mode) state.data.valvulaMode = p.valve_mode;
    if (p.modo_proteccion) state.data.modoSeguridad = p.modo_proteccion;
    if (p.command_result) {
      state.lastCommand = { ts: now, result: p.command_result, error: p.valve_error || p.fan_error };
      if (p.command_result.startsWith("REJECT")) {
        const key = p.valve_error === "interlock_active" ? "REJECTED_INTERLOCK" : p.command_result;
        const texto = HUMAN_EVENTS[key] || ("Comando rechazado: " + p.command_result);
        state.events.unshift({ ts: now, text: texto, level: "warning" });
      }
    }
  }

  // --- CANAL FORMAL DE AUDITORIA: EVENTOS Y ALERTAS MQTT ---
  else if (t.includes("/evento/") || t.includes("/alerta/")) {
    if (p && (p.event || p.alert_id)) {
      const eventTs = p.timestamp ? Date.parse(p.timestamp) : now;
      const severity = String(p.severity || (t.includes("/alerta/") ? "critical" : "info")).toLowerCase();
      const rawEvent = p.event || p.alert_id;
      const humanText = HUMAN_EVENTS[rawEvent] || p.text || rawEvent;

      // Actualizar estado de modoSeguridad si viene de evento de seguridad
      if (rawEvent === "ACCEPTED_ARM") state.data.modoSeguridad = "ARM";
      if (rawEvent === "ACCEPTED_DISARM") state.data.modoSeguridad = "DISARM";

      // 1. Registro de evento historico
      const existe = state.events.some(e => e.text === humanText && Math.abs(e.ts - eventTs) < 1000);
      if (!existe) {
        state.events.unshift({
          ts: Number.isFinite(eventTs) ? eventTs : now,
          text: humanText,
          level: severity === "critical" ? "critical" : severity === "warning" ? "warning" : "info"
        });
      }

      // 2. Mantenimiento de Alarmas Activas Reales recibidas por MQTT
      if (t.includes("/alerta/")) {
        const alertKey = p.alert_id || t.split("/").pop();
        if (p.active === true) {
          state.activeAlerts[alertKey] = {
            id: alertKey,
            level: severity === "critical" ? "critical" : "warning",
            text: p.text || humanText,
            ts: Number.isFinite(eventTs) ? eventTs : now
          };
        } else if (p.active === false) {
          delete state.activeAlerts[alertKey];
        }
      }
    }
  }
}

state.events = state.events.slice(0, 25);
global.set("bunkerCore", state);

msg.state = state;
return msg;

const { state } = msg;
if (!state || !state.data) return null;

const d = state.data;
const meteo = state.meteo || {};

// Obtenemos directamente las alertas legítimas originadas en el Edge por MQTT
const alertsMap = Object.assign({}, state.activeAlerts || {});

// Única regla Cloud: Correlación externa OWM con estado físico local
if (d.puertaAbierta === true && meteo.lluvia === true) {
  alertsMap['correlacion_lluvia_escotilla'] = {
    id: 'correlacion_lluvia_escotilla',
    level: 'critical',
    text: '¡Riesgo de inundación! Escotilla abierta durante lluvia exterior'
  };
} else {
  delete alertsMap['correlacion_lluvia_escotilla'];
}

const alerts = Object.values(alertsMap);

msg.payload = {
  mode: 'live',
  data: d,
  alerts,
  events: state.events,
  history: state.history,
  meteo: state.meteo,
  lastUpdate: state.lastUpdate,
  lastCommand: state.lastCommand,
  complete: d.temperatura !== null && d.humedad !== null && d.nivelAgua !== null && d.puertaAbierta !== null
};
msg.topic = 'bunkeros/state';

return msg;

const BASE = env.get("MQTT_BASE_TOPIC");
const action = String(msg.payload || '');
const state = global.get('bunkerCore') || { events: [] };
const now = Date.now();

const ACTION_MAP = {
  'FAN_ON':     { subtopic: '/control/ventilacion', payload: { target: 'fan', action: 'ON' } },
  'FAN_OFF':    { subtopic: '/control/ventilacion', payload: { target: 'fan', action: 'OFF' } },
  'FAN_AUTO':   { subtopic: '/control/ventilacion', payload: { target: 'fan', action: 'AUTO' } },
  'VALVE_OPEN': { subtopic: '/control/valvula',     payload: { target: 'valve', action: 'OPEN' } },
  'VALVE_CLOSE':{ subtopic: '/control/valvula',     payload: { target: 'valve', action: 'CLOSE' } },
  'VALVE_AUTO': { subtopic: '/control/valvula',     payload: { target: 'valve', action: 'AUTO' } },
  'SEC_ARM':    { subtopic: '/control/seguridad',   payload: { target: 'security', action: 'ARM' } },
  'SEC_DISARM': { subtopic: '/control/seguridad',   payload: { target: 'security', action: 'DISARM' } }
};

const cmd = ACTION_MAP[action];
if (!cmd) return null;

cmd.payload.requested_by = 'dashboard_admin';
cmd.payload.timestamp = new Date(now).toISOString();

if (action === 'SEC_ARM') state.data = Object.assign(state.data || {}, { modoSeguridad: 'ARM' });
if (action === 'SEC_DISARM') state.data = Object.assign(state.data || {}, { modoSeguridad: 'DISARM' });

state.lastCommand = { ts: now, action, status: 'DISPATCHED_TO_EDGE' };
// Intención despachada: el log de auditoría se registrará cuando el Edge confirme por MQTT
global.set('bunkerCore', state);

return { topic: BASE + cmd.subtopic, payload: cmd.payload };

const BASE = env.get("MQTT_BASE_TOPIC") || "bunker/g5";
